System.register("chunks:///_virtual/manifest2.ts",["cc"],(function(e){var a;return{setters:[function(e){a=e.cclegacy}],execute:function(){a._RF.push({},"d4351z4eXlEPoofak/0nLOD","manifest",void 0);e("MANIFEST",{manifest_version:1,game_id:"sg-solitaire",slug:"solitaire",name:{en:"Solitaire",it:"Solitario"},description:{en:"Classic Klondike solitaire. Tap a card and it jumps where it fits.",it:"Il solitario Klondike classico. Tocca una carta e salta dove va."},genre:"card",template_id:"cards",engine:"cocos-3.8.8",version:"1.0.0",orientation:"portrait",game_rules:{variant:"klondike",max_moves:1500,modes:[{id:"draw1",draw:1},{id:"draw3",draw:3}]},scoring_rules:{points:"standard",recycle_penalty_draw1:100,recycle_penalty_draw3:20,undo_penalty:15,time_bonus_max:1e3,time_bonus_window_s:600},supported_platforms:["web","telegram"],supported_locales:["en","it"],default_locale:"en",target_countries:["*"],age_rating:"PEGI 3",privacy_profile:{personal_data:!1,analytics:"pseudonymous_install",account_required:!1},monetization_profile:{rewarded_ads:!1,interstitial_ads:!1,iap:!0},social_profile:{share:!0,leaderboard:!0,challenge:!0},analytics_profile:{sink:"memory",flush_interval_ms:5e3},difficulty_config:{level:"normal"},asset_manifest:{theme:"settegames",palette:{background:"#18B98F",primary:"#FF2D8B",accent:"#FFC83D",text:"#1A0B4B",muted:"#F4F6FF"},sounds:"synth",provenance:"Tavolo verde-acqua (#18B98F, contrasto 7:1 con l'inchiostro viola-scuro del brand) con rosa, giallo, viola-scuro e bianco-lavanda del brand kit SetteGames; caratteri Titan One e Baloo 2 (OFL, da Scopa, come Perfect Timer); suoni sintetizzati dal codice; carte (mazzo francese standard: indici, semi disegnati come forme geometriche, dorso) disegnate dal codice. Nessun asset di terzi. Direzione: .impeccable.md"},build_config:{targets:["web-mobile"],max_gzip_kb:1200},release_config:{channels:["web","telegram"],status:"draft"},legal_status:{original_concept:!1,trademark_check:"pending",gambling_mechanics:!1,notes:'"Solitaire"/"Solitario" e "Klondike" sono nomi generici di un gioco di carte tradizionale di pubblico dominio (XIX secolo). Nessun codice, grafica, dorso, suono o testo presi da Microsoft Solitaire Collection o da altre app: regole reimplementate da zero (templates/cards/logic), carte del mazzo francese standard disegnate dal codice (indici, semi geometrici, dorso SetteGames), palette del brand SetteGames. Nessun marchio di terzi nelle parole chiave SEO (niente "Microsoft", "Windows", "Spider" come marchio). Nessuna scommessa, nessun premio in denaro: il punteggio serve solo per record e classifica. Da confermare il controllo marchi prima della pubblicazione.'},experiment_config:{active:[]},seo:{keywords:["solitaire","klondike solitaire","play solitaire online","free solitaire","solitaire card game","draw 3 solitaire","patience card game"],headline:{en:"Play Klondike Solitaire online",it:"Gioca al Solitario Klondike online"},long_description:{en:"Solitaire is the classic Klondike card game you can play for free in your browser or on Telegram, with no download and no sign-up. Tap a card and it jumps to the best spot, or drag it where you want. Build the four foundations from Ace to King, choose relaxed Draw 1 or tougher Draw 3, then challenge a friend to beat your score on the weekly leaderboard.",it:"Solitario è il classico gioco di carte Klondike che puoi giocare gratis nel browser o su Telegram, senza scaricare nulla e senza registrarti. Tocca una carta e salta nel posto migliore, oppure trascinala dove vuoi. Costruisci le quattro fondazioni dall'Asso al Re, scegli Pesca 1 per rilassarti o Pesca 3 per la sfida, poi sfida un amico a battere il tuo punteggio nella classifica della settimana."},how_to_play:{en:["The goal is to move all 52 cards to the four foundations at the top, one per suit, from Ace up to King.","In the seven columns, build down in alternating colors: a red 6 goes on a black 7.","You can move a whole run of face-up cards at once. Only a King (or a run starting with a King) can fill an empty column.","When a face-down card is left on top of a column, it flips over by itself.","Tap the deck to turn over 1 card (Draw 1) or 3 cards (Draw 3). When it runs out, tap again to flip the pile back.","Tap any card to move it automatically, or drag it to the spot you choose. When every card is face up, Auto-finish completes the game."],it:["Lo scopo è portare tutte le 52 carte nelle quattro fondazioni in alto, una per seme, dall'Asso al Re.","Nelle sette colonne si scende alternando i colori: un 6 rosso va su un 7 nero.","Puoi spostare in un colpo solo una sequenza di carte scoperte. In una colonna vuota va solo un Re (o una sequenza che parte da un Re).","Quando in cima a una colonna resta una carta coperta, si gira da sola.","Tocca il mazzo per girare 1 carta (Pesca 1) o 3 carte (Pesca 3). Quando finisce, toccalo di nuovo per rigirare gli scarti.","Tocca una carta per spostarla da sola, oppure trascinala dove vuoi. Quando tutte le carte sono scoperte, Completa chiude la partita."]},faq:[{q:{en:"Is this solitaire free to play?",it:"Questo solitario è gratis?"},a:{en:"Yes. You play the full game for free in your browser or on Telegram, with no download and no account. Optional color themes are cosmetic only and never change the game or your score.",it:"Sì. Il gioco completo è gratis nel browser o su Telegram, senza download e senza account. I temi colore facoltativi sono solo estetici e non cambiano mai il gioco né il punteggio."}},{q:{en:"What is the difference between Draw 1 and Draw 3?",it:"Che differenza c'è fra Pesca 1 e Pesca 3?"},a:{en:"In Draw 1 each tap on the deck turns over one card, so you see every card on each pass: most deals can be won. In Draw 3 you turn three cards at a time and can only play the top one, which makes the game much harder. Both modes allow unlimited passes through the deck, and each mode has its own best score and leaderboard.",it:"In Pesca 1 ogni tocco sul mazzo gira una carta, quindi a ogni giro le vedi tutte: si vince la maggior parte delle partite. In Pesca 3 se ne girano tre alla volta e si gioca solo quella in cima, ed è molto più difficile. In entrambe le modalità il mazzo si può rigirare senza limiti, e ognuna ha il suo record e la sua classifica."}},{q:{en:"What is the best strategy for Klondike solitaire?",it:"Qual è la strategia migliore per il solitario Klondike?"},a:{en:"Flip face-down cards as early as possible, starting with the longest columns: they hide the most cards. Prefer moves from the columns over plays from the deck, and don't empty a column unless you have a King ready to move into it.",it:"Scopri le carte coperte il prima possibile, partendo dalle colonne più lunghe: nascondono più carte. Preferisci le mosse fra le colonne a quelle dal mazzo, e non svuotare una colonna se non hai un Re pronto da metterci."}},{q:{en:"Should I always move cards to the foundations right away?",it:"Conviene mettere subito le carte nelle fondazioni?"},a:{en:"Aces and twos, always. Higher cards can wait: a black 5 still in a column may be the only place where you can park a red 4 and free the card underneath. Move them up when they are no longer useful as a landing spot.",it:"Assi e due, sempre. Le carte più alte possono aspettare: un 5 nero ancora in colonna può essere l'unico posto dove appoggiare un 4 rosso e liberare la carta sotto. Portale su quando non servono più come appoggio."}},{q:{en:"How is the score calculated? Can I undo?",it:"Come si calcola il punteggio? Si può annullare?"},a:{en:"You get 10 points for each card on a foundation, 5 for each card moved from the deck to a column and 5 for each face-down card you flip. Flipping the deck back costs points, and so does each undo. Win the game to earn a time bonus: the faster you finish, the bigger it is. Scores are checked by replaying your moves on our server.",it:"Ogni carta in fondazione vale 10 punti, ogni carta dal mazzo a una colonna 5 e ogni carta coperta che giri 5. Rigirare il mazzo costa punti, e anche ogni annullamento. Vinci la partita per il bonus tempo: più sei veloce, più è alto. I punteggi vengono verificati rigiocando le tue mosse sul nostro server."}},{q:{en:"Can every game of solitaire be won?",it:"Si possono vincere tutte le partite di solitario?"},a:{en:"No. A small share of Klondike deals cannot be solved whatever you do, and many more are lost by one early choice. If you run out of useful moves, end the game: your score still counts for the leaderboard.",it:"No. Una piccola parte delle distribuzioni del Klondike non si può risolvere in nessun modo, e molte altre si perdono per una scelta all'inizio. Se finisci le mosse utili, termina la partita: il punteggio conta comunque per la classifica."}}]}}),e("BUILD_INFO",{hash:"1d094c7ae97513e6",hubUrl:"https://jvmpwhoosojharlbmgsi.supabase.co/functions/v1/hub-api"});a._RF.pop()}}}));

